const list=Array.isArray(j)?j:(Array.isArray(j.result)?j.result:[j.result||j]);
const t=list.find(x=>x&&x.task_id===tid)||{};
console.log("status:",t.status,"| stage:",t.stage,"| secs:",Math.round(t.processing_seconds||0));
if(t.result){
 console.log("extracted:",JSON.stringify(t.result.memories_extracted));
 console.log("tokens:",JSON.stringify(t.result.token_usage?.total));
 console.log("skills:",t.result.session_skills_extracted);
 console.log("err:",JSON.stringify(t.error));
}
